cedar:
@id("hl-corewriter-no-short-perp")
@severity("deny")
@reason("Opening a new short perp through Hyperliquid CoreWriter is blocked by policy")
forbid(principal, action == HyperliquidCore::Action::"HlCoreLimitOrder", resource)
when {
  context.venue.name == "hyperliquid"
    && context.side == "short"
    && context.reduceOnly == false
};

@id("hl-confirm-approve-agent")
@severity("warn")
@reason("Authorizing an agent wallet to trade on your behalf — confirm before approving")
forbid(principal, action == Permission::Action::"ProtocolAuthorization", resource)
when {
  context.protocolName == "hyperliquid"
    && context.permission == "agent"
    && context.isAuthorized == true
};
